import re
import copy
import sys
from ta_pdml_parser.asnParser import ConvertAsnToPythonStructure


class QxdmLogParser(object):

    class ParsingDone(Exception):
        pass

    _PYTHON_VERSION = sys.version_info
    _NEW_LINE_REGEX = r'(?<!\r)\n|\r(?!\n)' if _PYTHON_VERSION[0] == 3 else r'\r\n'

    def __init__(self, file_path, message_ids=None, group_by_message_id=True, table_dict_format=False,
                 encoding='iso-8859-15'):
        """

        :param file_path: absolute path to txt qxdm log.
        :param message_ids: List of id to filter eg
                                ['0xB89B', '0xB896']
                            or list of dict:
                                [{'id': '0xB821', 'name': 'NR5G RRC OTA Packet  --  DL_DCCH / RRCReconfiguration'},]
        :param group_by_message_id: if False - return list of all message. If True return dict of list.
        :param table_dict_format: flag True/False - if True additional key 'dict' available in table results
        """
        self.file_path = file_path
        self.message_ids = message_ids
        self.group_by_message_id = group_by_message_id
        self.table_dict_format = table_dict_format
        self.encoding = encoding

        self._ret = {} if group_by_message_id else []
        self._single_message = {}
        self._dict = {}
        self._single_table = {}

        # flags
        self._mode = None
        self._headers = []
        self._values = []

        self._indent_size = 3
        self._last_key_name = []

        # TODO records in table as list of dicts - you can choose format
        # TODO Sub Packets as list of dict
        # TODO Create separate class for parsing table

    @property
    def ret(self):
        """
        Results of parsing.
        :return: list or dict - depends of group_by_message_id parameter
        """
        return self._ret

    def _read_line(self):
        params = {}
        if QxdmLogParser._PYTHON_VERSION[0] == 3:
            params['encoding'] = self.encoding
        with open(self.file_path, 'r', **params) as f:
            for line in f:
                yield line

    def parse(self):
        for line in self._read_line():
            try:
                self._parse_message_start(line)
                if self._parsed_message_in_message_ids():
                    if self._mode == "message_start" or self._mode == "table_end" or self._mode == "asn_message_end":
                        self._parse_asn_message_start(line)
                        self._parse_one_line_with_sub_id(line)
                        self._parse_dict(line)
                        self._parse_key(line)
                        self._parse_table_headers_start(line)
                    elif self._mode == "header_start":
                        self._parse_headers(line)
                        self._parse_table_headers_end(line)
                    elif self._mode == "header_end":
                        self._parse_table_values(line)
                        self._parse_table_end(line)
                    elif self._mode == "asn_message_start":
                        self._gather_asn_message(line)
                else:
                    self._clear_vars()

            except QxdmLogParser.ParsingDone:
                pass

        if self._parsed_message_in_message_ids():
            self._add_single_message_to_results()

    def _parsed_message_in_message_ids(self):
        if self._single_message:
            if not self.message_ids or self._check_if_message_in_message_ids():
                return True
        return False

    def _check_if_message_in_message_ids(self):
        current_message = self._single_message['message']
        for message_id in self.message_ids:
            if isinstance(message_id, dict):
                if message_id['id'] == current_message['id'] and message_id['name'] == current_message['name']:
                    return True
            else:
                if message_id == current_message['id']:
                    return True
        return False

    def _add_single_message_to_results(self):
        if self._single_message:
            if self._values:
                self._add_table_to_dict()
            if isinstance(self._ret, dict):
                if not self._ret.get(self._single_message['message']['id'], None):
                    self._ret[self._single_message['message']['id']] = []
                self._ret[self._single_message['message']['id']].append(self._single_message)
            else:
                self._ret.append(self._single_message)
            self._clear_vars()

    # 1980 Feb  8  02:36:27.884  [EC]  0x1FEA  Diagnostic Request  --  Timestamp Request
    # 1980 Feb  8  02:36:31.108  [5A]  0xB888  NR5G MAC PDSCH Stats

    _re_message_timestamp = re.compile(r'(?P<date>^\d{{4}}\s+\w+\s+\d+)\s+(?P<time>\d+:\d+:\d+\.\d+)'
                                       r'.*(?P<id>0x[0-9A-F]+)\s+(?P<name>.*){}'.format(_NEW_LINE_REGEX))

    def _parse_message_start(self, line):
        match = QxdmLogParser._re_message_timestamp.search(line)
        if match:
            self._add_single_message_to_results()
            self._single_message['message'] = match.groupdict()
            self._mode = "message_start"
            raise QxdmLogParser.ParsingDone

    # Interpreted PDU:
    # value BCCH-DL-SCH-Message ::=
    _re_asn_message_start = re.compile(r'value\s+(?P<MESSAGE_VALUE>.*)\s+::=')

    def _parse_asn_message_start(self, line):
        match = QxdmLogParser._re_asn_message_start.search(line)
        if match:
            self._message_results = []
            self._message_results.append(line.rstrip('\n'))
            self._mode = "asn_message_start"
            raise QxdmLogParser.ParsingDone

    _re_asn_message_end = re.compile(r'^' + r'{}'.format(_NEW_LINE_REGEX))

    def _gather_asn_message(self, line):
        if not QxdmLogParser._re_asn_message_end.search(line):
            self._message_results.append(line.rstrip('\n'))
            raise QxdmLogParser.ParsingDone
        else:
            joined_msg = "\n" + "\n".join(self._message_results)
            self._dict.update(ConvertAsnToPythonStructure(joined_msg).get()[0])
            self._mode = "asn_message_end"

    #     nr5g_l2ul_qsh.c     1727     H     Sub-ID:1     Misc-ID:0     ENL2UL   | NR | State | {rbIdx: 4}
    #     | pdcp:[nxtCNT: 77; flowSt: 0] | QAnalysis: 0x08500B63
    _re_one_line_results = re.compile(r'Sub-ID:(?P<SUB_ID>\d+)\s+Misc-ID:(?P<MISC_ID>\d+)(?P<REST_PART>.*)')
    # rbIdx: 4
    _re_key_value_separate_by_colon = re.compile(r'(?P<KEY>[\w.#%*]+):\s+(?P<VALUE>\w+)')
    # pdcp:[nxtCNT: 77; flowSt: 0]
    _re_key_list_key_values = re.compile(r'(?P<KEY>[\w.#%*]+):\[(?P<VALUES>.*?)]')

    def _parse_one_line_with_sub_id(self, line):
        match = QxdmLogParser._re_one_line_results.search(line)
        if not match:
            return
        results = {
            'Sub-ID': match.group('SUB_ID'),
            'Misc-ID': match.group('MISC_ID'),
        }
        rest_parts = match.group('REST_PART').split('|')
        final_part_dict = {}
        part_dict = final_part_dict
        for part in rest_parts:
            part = part.strip()
            if ':' not in part:
                part_dict[part] = {}
                part_dict = part_dict[part]
            elif ':[' in part:
                match_dict_list = QxdmLogParser._re_key_list_key_values.search(part)
                if match_dict_list:
                    list_values = match_dict_list.group('VALUES').split(';')
                    temp_dict = part_dict[match_dict_list.group('KEY')] = {}
                    for value_pair in list_values:
                        match_dict = QxdmLogParser._re_key_value_separate_by_colon.search(value_pair)
                        if match_dict:
                            temp_dict[match_dict.group('KEY')] = match_dict.group('VALUE')
            else:
                if part.startswith('{') and part.endswith('}'):
                    part = part.strip('{}')
                match_dict = QxdmLogParser._re_key_value_separate_by_colon.search(part)
                if match_dict:
                    part_dict[match_dict.group('KEY')] = match_dict.group('VALUE')
        results.update(final_part_dict)
        self._single_message['results'] = results
        raise QxdmLogParser.ParsingDone

    # Num Total Slots            = 396374
    _re_key_value = re.compile(r'^(?P<SPACE>\s*)(?P<KEY>[\w\s\.]+\b)\s+=\s+(?P<VALUE>.*){}'.format(_NEW_LINE_REGEX))

    def _parse_dict(self, line):
        match = QxdmLogParser._re_key_value.search(line)
        if match:
            self._set_dict(match)
            self._dict[match.group('KEY')] = match.group('VALUE')
            raise QxdmLogParser.ParsingDone

    # TX IU Power Sub Packet
    _re_key = re.compile(r'^(?P<SPACE>\s*)(?P<KEY>[\w\s\.]+\b(\[\d+\])?){}'.format(_NEW_LINE_REGEX))

    # 02 8E 1C 00 07 0C A2 80 50 00 E2 80
    _re_hex_value = re.compile(r'([0-9A-F]{2}\s){2,}[0-9A-F]')

    def _parse_key(self, line):
        match = QxdmLogParser._re_key.search(line)
        if match:
            if not QxdmLogParser._re_hex_value.search(line):  # ignoring payload message
                self._set_dict(match)
                self._dict[match.group('KEY')] = {}
                self._dict = self._dict[match.group('KEY')]
            raise QxdmLogParser.ParsingDone

    _re_headers_start_end = re.compile(r'--------------------------------')

    def _parse_table_headers_start(self, line):
        match = QxdmLogParser._re_headers_start_end.search(line)
        if match:
            self._mode = "header_start"
            raise QxdmLogParser.ParsingDone

    _re_tab_headers_values = re.compile(r'\|(.*?)\|')

    def _parse_headers(self, line):
        match = QxdmLogParser._re_tab_headers_values.search(line)
        if match:
            headers = line.split('|')
            del headers[0]
            del headers[-1]
            self._headers.insert(0, [{'name': header.strip(), 'len': len(header)} for header in headers])
            raise QxdmLogParser.ParsingDone

    def _parse_table_headers_end(self, line):
        match = QxdmLogParser._re_headers_start_end.search(line)
        if match:
            self._single_table['headers'] = self._build_list_of_headers()
            self._headers = []
            self._mode = "header_end"
            raise QxdmLogParser.ParsingDone

    def _parse_table_values(self, line):
        # |  0| 1018|   3|  30kHz|  1|0x00000000|4A71CDC6|FFFF321C|     2|     0|      1|      0|
        match = QxdmLogParser._re_tab_headers_values.search(line)
        if match:
            values = line.split('|')
            del values[0]
            del values[-1]
            self._values.append([value.strip() for value in values])
            raise QxdmLogParser.ParsingDone

    # when new line - means that it;s end of table
    _re_table_end = re.compile(r'^' + r'{}'.format(_NEW_LINE_REGEX))

    def _parse_table_end(self, line):
        match = QxdmLogParser._re_table_end.search(line)
        if match:
            self._add_table_to_dict()
            self._mode = "table_end"
            raise QxdmLogParser.ParsingDone

    def _build_list_of_headers(self):
        new_headers = [record['name'] for record in self._headers[0]]
        total_len = {}
        for new_index, new_header in enumerate(new_headers):
            previous_len = self._headers[0][new_index]['len']
            for row_id, header_row in enumerate(self._headers[1:], 1):
                current_len = header_row[0]['len']
                current_header_name = header_row[0]['name']

                if current_len == previous_len:
                    total_len[row_id] = previous_len
                    if current_header_name:
                        new_headers[new_index] = current_header_name + ' ' + new_headers[new_index]

                if current_len > previous_len:
                    new_headers[new_index] = current_header_name + '->' + new_headers[new_index]
                    if total_len.get(row_id, 0):
                        total_len[row_id] = total_len[row_id] + previous_len + 1
                    else:
                        total_len[row_id] = total_len[row_id] + previous_len

                if self._remove_record(row_id, total_len, current_len):
                    del header_row[0]
                    total_len[row_id] = 0

                previous_len = current_len

        return new_headers

    @staticmethod
    def _remove_record(row_id, total_len, current_len):
        remove_record = False
        if total_len[row_id] == current_len:
            if row_id == 1 or total_len[row_id - 1] == 0:
                remove_record = True

        return remove_record

    def _set_dict(self, match):
        indent_level = int(len(match.group('SPACE')) / self._indent_size)
        self._last_key_name.insert(indent_level, match.group('KEY'))
        self._dict = self._single_message
        for index in range(0, indent_level):
            self._dict = self._dict[self._last_key_name[index]]

    def _add_table_to_dict(self):
        self._single_table['values'] = self._values
        if self.table_dict_format:
            converter = TableToDictConverter(headers=self._single_table['headers'],
                                             values=self._single_table['values'])
            converter.convert_table_results_to_dict()
            self._single_table['dict'] = copy.copy(converter.results)

        if self._dict:
            self._dict['Records'] = {}
            self._dict = self._dict['Records']

        self._dict.update(self._single_table.copy())
        self._values = []

    def _clear_vars(self):
        self._single_message = {}
        self._single_table = {}
        self._dict = {}
        self._last_key_name = []


class TableToDictConverter(object):

    def __init__(self, headers, values):
        self.headers = headers
        self.values = values
        self.results = []
        self._all_key_path = []

    def _get_all_key_path_to_update(self, _dict, keys_from_root, prev_key=None):
        for key_index, _key in enumerate(_dict.keys()):
            if isinstance(_dict[_key], dict):
                if prev_key:
                    other_path = []
                    for _header in keys_from_root:
                        other_path.append(_header)
                        if _header == prev_key:
                            break
                    self._all_key_path.append(other_path)
                if len(_dict[_key].keys()) > 1:
                    prev_key = _key
                keys_from_root.append(_key)
                keys_from_root = self._get_all_key_path_to_update(_dict[_key], keys_from_root, prev_key)
                if keys_from_root:
                    self._all_key_path.append(keys_from_root)
                    keys_from_root = []

        return keys_from_root

    def _convert_to_simple_dict(self, record):
        record_dict = {}
        for column_index, header in enumerate(self.headers):
            if record[column_index]:
                keys = header.split('->')
                _dict = record_dict
                for index, key in enumerate(keys):
                    if len(keys) == index + 1:
                        _dict[key] = record[column_index]
                    elif key not in _dict:
                        _dict[key] = {}

                    _dict = _dict[key]

        return record_dict

    def convert_table_results_to_dict(self):
        for record_index, record in enumerate(self.values):
            record_dict = self._convert_to_simple_dict(record)
            if record_dict.get('#', None):
                self.results.append(record_dict.copy())
                next_index = record_index + 1
                if next_index < len(self.values):
                    next_record_dict = self._convert_to_simple_dict(self.values[next_index])
                    if next_record_dict.get('#', None):
                        continue
                elif record_index + 1 == len(self.values):
                    continue
            self._all_key_path = []
            self._get_all_key_path_to_update(record_dict, [])
            prev_results = self.results[-1]
            for path_to_merge in self._all_key_path:
                content_to_append = record_dict
                content_to_merge = prev_results
                dict_to_change = prev_results
                for key_index, subkey in enumerate(path_to_merge):
                    if key_index > 0:
                        if isinstance(content_to_merge, dict):
                            dict_to_change = content_to_merge
                        else:
                            dict_to_change = content_to_merge[-1]
                    if isinstance(content_to_merge, dict):
                        content_to_merge = content_to_merge[subkey]
                    else:
                        content_to_merge = content_to_merge[-1][subkey]
                    content_to_append = content_to_append[subkey]

                if isinstance(content_to_merge, dict):
                    to_merge = content_to_merge.copy()
                    dict_to_change[path_to_merge[-1]] = []
                    dict_to_change[path_to_merge[-1]].append(to_merge)
                else:
                    dict_to_change[path_to_merge[-1]].append(content_to_append)


